-    connect(m_nextSlideAction, &QAction::triggered, this, &ImageBackend::nextSlide);
+    connect(m_nextSlideAction, &QAction::triggered, this, [this] {
+        if (!isSynchronizedSlideshow()) {
+            nextSlide();
+            return;
+        }
+        ++s_synchronizedSkip;
+        for (ImageBackend *backend : std::as_const(*s_backends)) {
