@@ -521,18 +569,24 @@ void ImageBackend::nextSlide()
     if (previousSlide >= 0) {
         previousUrl = m_slideFilterModel->index(m_currentSlide, 0).data(ImageRoles::SourceRole).toUrl();
     }
-    if (m_currentSlide >= rowCount - 1 /* ">" in case the last wallpaper is deleted before */ || m_currentSlide < 0) {
+    const bool synchronized = isSynchronizedSlideshow();
+    if (synchronized) {
+        // Every synchronized slideshow derives its image from the current time slot, so all screens show the same one
+        const qint64 slot = (m_delay > 0 ? QDateTime::currentMSecsSinceEpoch() / (qint64(m_delay) * 1000) : 0) + s_synchronizedSkip;
+        m_slideFilterModel->setRandomSeed(slot / rowCount);
+        m_currentSlide = slot % rowCount;
+    } else if (m_currentSlide >= rowCount - 1 /* ">" in case the last wallpaper is deleted before */ || m_currentSlide < 0) {
         m_currentSlide = 0;
     } else {
         m_currentSlide += 1;
     }
     // We are starting again - avoid having the same random order when we restart the slideshow
-    if (m_slideshowMode == SortingMode::Random && m_currentSlide == 0) {
+    if (!synchronized && m_slideshowMode == SortingMode::Random && m_currentSlide == 0) {
         m_slideFilterModel->invalidate();
     }
     QUrl next = m_slideFilterModel->index(m_currentSlide, 0).data(ImageRoles::SourceRole).toUrl();
     // And  avoid showing the same picture twice
-    if (previousSlide == rowCount - 1 && previousUrl == next && rowCount > 1) {
+    if (!synchronized && previousSlide == rowCount - 1 && previousUrl == next && rowCount > 1) {
         m_slideFilterModel->swapFirstWithRandom();
         next = m_slideFilterModel->index(m_currentSlide, 0).data(ImageRoles::SourceRole).toUrl();
     }
