+void SlideFilterModel::setRandomSeed(qint64 seed)
+{
+    if (!sourceModel() || m_randomSeed == seed) {
+        return;
+    }
+    m_randomSeed = seed;
+    m_randomOrder = seededRandomOrder(seed);
+
+    // Avoid showing the same picture twice when one round ends and the next one starts
+    const auto visibleRows = [this](const QList<int> &order) {
+        QList<int> rows;
+        std::copy_if(order.cbegin(), order.cend(), std::back_inserter(rows), [this](int row) {
+            return filterAcceptsRow(row, {});
+        });
+        return rows;
+    };
+    const QList<int> current = visibleRows(m_randomOrder);
+    if (seed > 0 && current.size() > 1 && visibleRows(seededRandomOrder(seed - 1)).constLast() == current.constFirst()) {
+        m_randomOrder.swapItemsAt(m_randomOrder.indexOf(current.at(0)), m_randomOrder.indexOf(current.at(1)));
+    }
+
+    QSortFilterProxyModel::invalidate();
+    sort(0);
+}
+
 int SlideFilterModel::indexOf(const QString &path)
 {
     if (!sourceModel())
@@ -272,9 +299,24 @@ void SlideFilterModel::deselectAllSlides()

 void SlideFilterModel::buildRandomOrder()
 {
+    m_randomSeed.reset();
     if (sourceModel()) {
         m_randomOrder.resize(sourceModel()->rowCount());
         std::iota(m_randomOrder.begin(), m_randomOrder.end(), 0);
         std::shuffle(m_randomOrder.begin(), m_randomOrder.end(), m_random);
     }
 }
+
+QList<int> SlideFilterModel::seededRandomOrder(qint64 seed) const
+{
+    // Start from an order that doesn't depend on how the images were found, so every wallpaper
+    // with the same images and the same seed gets the same order
+    QList<int> order(sourceModel()->rowCount());
+    std::iota(order.begin(), order.end(), 0);
+    std::sort(order.begin(), order.end(), [this](int left, int right) {
+        return sourceModel()->index(left, 0).data(ImageRoles::SourceRole).toUrl() < sourceModel()->index(right, 0).data(ImageRoles::SourceRole).toUrl();
+    });
+    std::mt19937 random(static_cast<std::mt19937::result_type>(seed));
+    std::shuffle(order.begin(), order.end(), random);
+    return order;
+}
